<?php
require_once __DIR__.'/includes/security.php'; require __DIR__.'/includes/db.php';require_once __DIR__.'/includes/customer-auth.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['product_id']??0);$action=$_POST['action']??'';if($action==='add'&&$id){$s=$pdo->prepare('SELECT stock FROM products WHERE id=? AND active=1');$s->execute([$id]);$p=$s->fetch();if($p){$_SESSION['cart'][$id]=min((int)$p['stock'],($_SESSION['cart'][$id]??0)+max(1,(int)($_POST['quantity']??1)));if($_SESSION['cart'][$id]<1)unset($_SESSION['cart'][$id]);}}elseif($action==='remove')unset($_SESSION['cart'][$id]);elseif($action==='update'){if((int)($_POST['quantity']??0)<1)unset($_SESSION['cart'][$id]);else{$s=$pdo->prepare('SELECT stock FROM products WHERE id=?');$s->execute([$id]);$stock=(int)$s->fetchColumn();$_SESSION['cart'][$id]=min($stock,(int)$_POST['quantity']);}}header('Location: cart.php');exit;}
$items=[];$subtotal=0;foreach($_SESSION['cart']??[] as $id=>$qty){$s=$pdo->prepare('SELECT * FROM products WHERE id=? AND active=1');$s->execute([(int)$id]);if($p=$s->fetch()){$qty=min((int)$qty,(int)$p['stock']);if($qty>0){$p['quantity']=$qty;$p['line_total']=$qty*(float)$p['price'];$subtotal+=$p['line_total'];$items[]=$p;}else unset($_SESSION['cart'][$id]);}else unset($_SESSION['cart'][$id]);}$shipping=$subtotal>=500000||$subtotal===0?0:20000;
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Keranjang — TokoKita</title><link rel="stylesheet" href="assets/style.css"></head><body><?php include __DIR__.'/includes/header.php' ?><main class="wrap"><div class="crumb"><a href="index.php">Beranda</a> / Keranjang</div><h1 class="page-title">Keranjang belanja</h1><?php if(!$items):?><div class="panel empty"><div>🛒</div><h3>Keranjangmu masih kosong</h3><p>Yuk, temukan produk yang kamu suka.</p><a class="btn" href="index.php">Mulai belanja →</a></div><?php else:?><div class="cart-layout"><section class="panel"><?php foreach($items as $p):?><div class="cart-item"><div class="cart-thumb"><?=render_emoji($p['emoji'])?></div><div><h3><?=e($p['name'])?></h3><p><?=rupiah($p['price'])?></p><form class="qty" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="update"><input type="hidden" name="product_id" value="<?=$p['id']?>"><button name="quantity" value="<?=$p['quantity']-1?>">−</button><span><?=$p['quantity']?></span><button name="quantity" value="<?=$p['quantity']+1?>">+</button></form></div><div><b><?=rupiah($p['line_total'])?></b><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="<?=$p['id']?>"><button class="remove">Hapus</button></form></div></div><?php endforeach?></section><aside class="panel summary"><h2>Ringkasan belanja</h2><div class="sumline"><span>Subtotal</span><span><?=rupiah($subtotal)?></span></div><div class="sumline"><span>Pengiriman</span><span><?=$shipping?'Rp 20.000':'Gratis'?></span></div><?php if($subtotal>0&&$subtotal<500000):?><div class="sumline"><small>Gratis ongkir untuk belanja minimal Rp 500.000</small></div><?php endif?><div class="sumline total"><span>Total</span><span><?=rupiah($subtotal+$shipping)?></span></div><a class="btn full" href="checkout.php">Lanjut ke checkout →</a></aside></div><?php endif?></main><?php include __DIR__.'/includes/footer.php' ?></body></html>